// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2, IERC1271} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
    }

    function testFuzz_property(uint256 duration, uint256 expOffset, uint256 nonce) public {
        // Keep duration admissible (< 10_000 days) and strictly positive so the recorded
        // expiration can never be zero, which is the sentinel for "key never written".
        duration = bound(duration, 1, 10_000 days - 1);
        expOffset = bound(expOffset, 1, 1_000_000);

        // A contract maker whose ERC-1271 signature is always valid: lets us fill an order
        // signed by a party the fuzzer does not need to synthesise a key for.
        Signer maker = new Signer();

        // Base asset must have code; the short-call path only does a zero-value
        // transferFrom(premium = 0), which this stub always accepts.
        StubToken token = new StubToken();

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(maker),
            isCall: true,
            isLong: false, // SHORT order: P writes the expiration under positionId, M under orderHash
            baseAsset: address(token),
            strike: 0,
            premium: 0,
            duration: duration,
            expiration: block.timestamp + expOffset,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        uint256[] memory noFloorIds = new uint256[](0);
        bytes memory emptySig = new bytes(0);

        vm.prank(address(maker));
        uint256 positionId = c.fillOrder(order, emptySig, noFloorIds);

        // positionId is the SHORT position's id (hash of the opposite, i.e. long, order).
        uint256 shortKey = uint256(c.hashOppositeOrder(order));
        require(positionId == shortKey, "position id mismatch");

        // GENERAL RULE: after filling a short order, the position's expiration
        // MUST be recorded under the short position's own id.
        assertTrue(
            c.positionExpirations(shortKey) == block.timestamp + duration,
            "short position expiration must be stored under its own position id"
        );
    }
}

contract Signer {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return IERC1271.isValidSignature.selector;
    }
}

contract StubToken {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    function transfer(address, uint256) external pure returns (bool) {
        return true;
    }
}
